import {renderCraftingDetail,focusFirstBlocker,craftReceiptText} from '../../src/crafting_detail.js';
import {itemRecipeStatus} from '../../src/crafting_visibility.js';
import {decorateActionComponents} from '../../src/ui_components.js';
const recipes=await fetch('built/recipes.json').then(r=>r.json());
const $=s=>document.querySelector(s), board=$('#board'), task=$('#task');
const state={variant:'compact',scenario:'ready',selected:recipes[0].id,stock:{},station:1,reserved:false,limited:false,view:'recipes',subject:null,history:[],query:'',listScroll:0,receipt:'',steps:0,running:true,unread:0};
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function button(text,fn,cls){const b=node('button',text,cls);b.type='button';b.onclick=fn;return b;}
function knownRecipes(){return state.limited?recipes.slice(0,1):recipes;}
function selected(){return knownRecipes().find(r=>r.id===state.selected)||knownRecipes()[0];}
function materialKnown(id){return !state.limited||id!=='Rat meat chunks';}
function lookup({material}){const count=state.stock[material.material_id]||0;return{count,items:[{item:{getInventoryKey:()=>material.material_id}}]};}
function status(r){const shim={...r,isUnlocked:()=>knownRecipes().some(x=>x.id===r.id),get_availability:()=>{const materials=r.materials.map(material=>lookup({material}));return{available_ammount:Math.min(...materials.map((g,i)=>Math.floor(g.count/r.materials[i].count))),materials};}};return itemRecipeStatus({recipe:shim,stationTier:state.station,findMaterial:lookup,isMaterialKnown:materialKnown,canConsume:()=>!state.reserved});}
function reason(r){const s=status(r);if(!state.station)return 'No cooking station here. Return to a place with cooking access.';const missing=s.requirements.filter(x=>x.missing);if(missing.length)return 'Missing '+missing.map(x=>`${x.need-x.have} ${materialKnown(x.material.material_id)?x.material.material_id:'unfamiliar material'}`).join(', ')+'.';if(state.reserved)return 'Materials are reserved by another commitment.';return '';}
function chance(r){const level=Math.min(5,r.levels[1])-r.levels[0]+1;return Math.round(100*r.chance[0]*(r.chance[1]/r.chance[0])**Math.min(1,level/(r.levels[1]-r.levels[0]+1)));}
function model(r){const s=status(r);return{title:r.name,requirements:s.requirements.map(x=>({label:materialKnown(x.material.material_id)?x.material.material_id:'Unfamiliar material',have:x.have,need:x.need,missing:x.missing,unknown:!materialKnown(x.material.material_id),held_back:x.held_back})),output:{name:r.name,count:r.outputCount,scaled:false},chance:chance(r),station:state.station?'Cooking, tier 1':'Cooking: not available here',xp:'Not simulated; production bonuses and XP are outside this comparison.',available:s.available,blocked_reason:reason(r),receipt:state.receipt,result_details:r.effects.map(x=>`${x.name} · duration ${x.duration} (native units)`).join('<br>')};}
function rememberView(){state.listScroll=$('.rows')?.scrollTop??state.listScroll;return{view:state.view,subject:state.subject,selected:state.selected,query:state.query,listScroll:state.listScroll,focus:document.activeElement?.dataset.restore||null};}
function openView(view,subject){state.history.push(rememberView());state.view=view;state.subject=subject;render();$('#task-title').focus();}
function back(){const prev=state.history.pop();if(!prev)return;Object.assign(state,prev);render();const target=[...document.querySelectorAll('[data-restore]')].find(n=>n.dataset.restore===prev.focus);target?.focus({preventScroll:true});}
function log(text,snapshot=null){const box=$('#log'),atBottom=box.scrollHeight-box.scrollTop-box.clientHeight<35;const row=node('div',undefined,'entry');row.append(node('time',`Step ${state.steps} · `),node('span',text));if(snapshot){const b=button('Inspect recorded attempt',()=>openView('event',structuredClone(snapshot)),'link');row.append(b);}box.append(row);if(atBottom)box.scrollTop=box.scrollHeight;else state.unread++;$('#unread').textContent=state.unread?`${state.unread} unread`:'';}
function simulate(r){if(!status(r).available){state.receipt=reason(r);render();return;}const used=r.materials.map(m=>({name:materialKnown(m.material_id)?m.material_id:'Unfamiliar material',count:m.count}));for(const m of r.materials)state.stock[m.material_id]-=m.count;state.stock[r.name]=(state.stock[r.name]||0)+r.outputCount;const text=craftReceiptText({made:r.outputCount,result_name:r.name,used,xp:0});state.receipt=text;const snapshot={title:r.name,text,step:state.steps};log(text+' · scripted success',snapshot);render();}
function renderStock(){const root=$('#stock');root.replaceChildren();for(const [id,count]of Object.entries(state.stock)){if(!materialKnown(id)||(state.limited&&(id==='Belmart leaf'||recipes.some(r=>r.id===id)&&!knownRecipes().some(r=>r.id===id))))continue;const row=node('div',undefined,'stock-row');row.append(node('span',id),node('span',String(count)));root.append(row);}}
function refButton(id,label=id){const b=button(label,()=>openView('reference',id),'link');b.dataset.restore='ref:'+id;return b;}
function recipeList(){const list=node('div',undefined,'recipe-list');const input=node('input');input.placeholder='Find known recipe';input.setAttribute('aria-label','Find known recipe');input.value=state.query;input.dataset.restore='search';const rows=node('div',undefined,'rows');rows.setAttribute('aria-label','Known recipes');function fill(){rows.replaceChildren();const shown=knownRecipes().filter(r=>r.name.toLowerCase().includes(state.query.toLowerCase()));for(const r of shown){const b=button('',()=>{state.listScroll=rows.scrollTop;state.selected=r.id;state.receipt='';render();[...document.querySelectorAll('[data-restore]')].find(n=>n.dataset.restore==='recipe:'+r.id)?.focus({preventScroll:true});},'recipe-row');b.append(node('span',r.name),node('small',status(r).available?'Ready':reason(r)));b.setAttribute('aria-pressed',String(r.id===selected().id));b.dataset.restore='recipe:'+r.id;rows.append(b);}if(!shown.length)rows.append(node('p','No matching known recipe. Clear search to return.','empty'));}input.oninput=()=>{state.query=input.value;fill();};fill();list.append(input,rows);requestAnimationFrame(()=>{rows.scrollTop=state.listScroll;});return list;}
function summary(r){const wrap=node('div',undefined,'summary'),body=node('div',undefined,'summary-body');body.append(node('h3',r.name),node('p',`Makes ${r.outputCount} · ${chance(r)}% base chance`));for(const req of model(r).requirements){const p=node('p');if(!req.unknown)p.append(refButton(req.label));else p.append(node('span',req.label));p.append(node('span',` · ${req.have} / ${req.need}`));body.append(p);}body.append(node('p',r.effects.map(e=>e.name).join(' + '),'muted result-effects'));body.append(node('p',reason(r)||'Cooking station ready.',reason(r)?'reason':'muted'));if(state.receipt)body.append(node('p',state.receipt,'receipt'));const actions=node('div',undefined,'summary-actions');const craft=button('Cook 1',()=>simulate(r),'primary');craft.setAttribute('aria-disabled',String(!status(r).available));craft.setAttribute('aria-describedby','compact-reason');const p=body.querySelector('.reason')||body.querySelector('.muted');p.id='compact-reason';const detail=button('Full recipe ›',()=>openView('full',r.id));detail.dataset.restore='full:'+r.id;actions.append(craft,detail);wrap.append(body,actions);return wrap;}
function fullRecipe(r){const body=node('div',undefined,'full-body');body.append(node('h3',r.name));const facts=[['Makes',`${r.outputCount} ${r.name}`],['Chance',`${chance(r)}% base at Cooking 5 / tier 1. Bonuses not simulated.`],['Station',state.station?'Cooking · tier 1':'Not available here'],['Result',r.effects.map(x=>`${x.name}, duration ${x.duration} native units`).join('; ')]];for(const [a,b]of facts){const row=node('div',undefined,'fact');row.append(node('strong',a),node('span',b));body.append(row);}const sec=node('section');sec.append(node('h3','Ingredients'));for(const m of model(r).requirements){const p=node('p');p.append(m.unknown?node('span',m.label):refButton(m.label),node('span',` · have ${m.have}, need ${m.need}${m.missing?`, missing ${m.need-m.have}`:''}${m.held_back?' · reserved':''}`));sec.append(p);}body.append(sec,node('p',reason(r)||'Ready to attempt. An attempt can fail in the game; this lab scripts a successful result.',reason(r)?'reason':'muted'));if(state.receipt)body.append(node('p',state.receipt,'receipt'));const actions=node('div',undefined,'full-actions'),b=button('Cook 1',()=>simulate(r),'primary');b.setAttribute('aria-disabled',String(!status(r).available));actions.append(b);task.append(body,actions);}
function renderReference(id){const body=node('div',undefined,'full-body');body.append(node('h3',id),node('p','Known reference · browsing does not travel or spend materials.','muted'),node('h3','Used for'));const related=knownRecipes().filter(r=>r.materials.some(m=>m.material_id===id));for(const r of related){const b=button(r.name,()=>{state.selected=r.id;openView('full',r.id);},'link');b.dataset.restore='use:'+r.id;body.append(b,node('p',r.materials.map(m=>`${m.count} ${materialKnown(m.material_id)?m.material_id:'unfamiliar material'}`).join(' + ')));}if(!related.length)body.append(node('p','No uses in your current known recipe list.'));body.append(node('p','Other acquisition routes are outside this comparison. This reference grants no station access.','muted'));task.append(body);}
function render(){renderStock();$('#station-state').textContent=state.station?'Cooking available · tier 1':'No cooking station in this fixture state.';task.replaceChildren();const expanded=state.view!=='recipes';board.dataset.expanded=String(expanded);$('#task-title').textContent=state.view==='reference'?'Reference':state.view==='event'?'Recorded attempt':'Cooking';$('#task-title').tabIndex=-1;const backButton=$('#back');backButton.hidden=!state.history.length;backButton.textContent=state.history.at(-1)?.view==='reference'?'← Reference':state.history.at(-1)?.view==='full'?'← Recipe':'← Cooking';$('#task-context').textContent=expanded?'Esc returns to previous view':'Village · cooking recipes';if(state.view==='reference')renderReference(state.subject);else if(state.view==='full')fullRecipe(selected());else if(state.view==='event'){const body=node('div',undefined,'full-body');body.append(node('h3',state.subject.title),node('p',`Recorded at step ${state.subject.step}`),node('p',state.subject.text),node('p','This is the recorded result, independent of current stock.','muted'));task.append(body);}else{const layout=node('div',undefined,'recipe-layout');layout.append(recipeList());if(state.variant==='compact')layout.append(summary(selected()));else{const detail=node('div',undefined,'crafting_detail');renderCraftingDetail(detail,model(selected()),{onCommit:()=>simulate(selected()),onBlocked:()=>focusFirstBlocker(detail)});detail.querySelector('[data-craft-commit]').textContent='Cook 1';for(const b of detail.querySelectorAll('[data-craft-amount]'))b.remove();const wrap=node('div',undefined,'summary');wrap.style.padding='0';const links=node('div',undefined,'reference-links');for(const m of selected().materials)if(materialKnown(m.material_id))links.append(refButton(m.material_id));wrap.append(links,detail);layout.append(wrap);}task.append(layout);}}
function reset(){Object.assign(state,{stock:{'Rat meat chunks':6,'Belmart leaf':2,'Stale bread':3,'Roasted rat meat':0,'Roasted purified rat meat':0},station:1,reserved:false,limited:false,view:'recipes',subject:null,history:[],query:'',listScroll:0,receipt:'',selected:recipes[0].id});if(state.scenario==='short')state.stock['Rat meat chunks']=1;if(state.scenario==='station')state.station=0;if(state.scenario==='reserved')state.reserved=true;if(state.scenario==='knowledge')state.limited=true;$('#log').replaceChildren();state.unread=0;$('#unread').textContent='';render();log('Known cooking recipes are available for inspection.');}
$('#variant').onchange=e=>{state.listScroll=$('.rows')?.scrollTop??state.listScroll;state.variant=e.target.value;render();};
$('#scenario').onchange=e=>{state.scenario=e.target.value;reset();};$('#reset').onclick=reset;
$('#text-size').onchange=e=>document.documentElement.style.fontSize=e.target.value+'px';$('#back').onclick=back;
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.history.length){e.preventDefault();back();}});
$('#pause-work').onclick=()=>{state.running=!state.running;$('#pause-work').textContent=state.running?'Pause routine':'Resume routine';};
$('#follow').onclick=()=>{$('#log').scrollTop=$('#log').scrollHeight;state.unread=0;$('#unread').textContent='';};
decorateActionComponents(document.body);reset();

log('Practice routine started. Opening references leaves it running.');
setInterval(()=>{if(!state.running)return;state.steps++;$('#work-progress').textContent=`${state.steps} steps`;if(state.steps%5===0)log('Practice routine continues. No recipe materials consumed.');},1000);
